data.platform-rules.json:
{
  "groups": [
    {
      "name": "platform-slo",
      "interval": "30s",
      "rules": [
        {
          "record": "module:availability:ratio",
          "expr": "sum by (module) (rate(http_requests_total{status!~\"5..\"}[5m])) / sum by (module) (rate(http_requests_total[5m]))"
        },
        {
          "record": "module:latency:p95_seconds",
          "expr": "histogram_quantile(0.95, sum by (le, module) (rate(http_request_duration_seconds_bucket[5m])))"
        },
        {
          "alert": "ModuleAvailabilityBelowSLO",
          "expr": "module:availability:ratio{module=\"audit-service\"} < 0.9995",
          "for": "10m",
          "labels": {
            "severity": "warning",
            "module": "audit-service"
          },
          "annotations": {
            "summary": "audit-service er under sit tilgængeligheds-SLO",
            "description": "SLO 99.95 % (docs/slo/audit-service.md)."
          }
        },
        {
          "alert": "ModuleLatencyAboveSLO",
          "expr": "module:latency:p95_seconds{module=\"audit-service\"} > 0.042",
          "for": "10m",
          "labels": {
            "severity": "warning",
            "module": "audit-service"
          },
          "annotations": {
            "summary": "audit-service har p95 over sit SLO",
            "description": "SLO 42 ms (docs/slo/audit-service.md)."
          }
        },
        {
          "alert": "ModuleAvailabilityBelowSLO",
          "expr": "module:availability:ratio{module=\"dummy-ok\"} < 0.9990000000000001",
          "for": "10m",
          "labels": {
            "severity": "warning",
            "module": "dummy-ok"
          },
          "annotations": {
            "summary": "dummy-ok er under sit tilgængeligheds-SLO",
            "description": "SLO 99.9 % (docs/slo/dummy-ok.md)."
          }
        },
        {
          "alert": "ModuleLatencyAboveSLO",
          "expr": "module:latency:p95_seconds{module=\"dummy-ok\"} > 0.25",
          "for": "10m",
          "labels": {
            "severity": "warning",
            "module": "dummy-ok"
          },
          "annotations": {
            "summary": "dummy-ok har p95 over sit SLO",
            "description": "SLO 250 ms (docs/slo/dummy-ok.md)."
          }
        },
        {
          "alert": "ModuleAvailabilityBelowSLO",
          "expr": "module:availability:ratio{module=\"mattermost-adapter\"} < 0.9990000000000001",
          "for": "10m",
          "labels": {
            "severity": "warning",
            "module": "mattermost-adapter"
          },
          "annotations": {
            "summary": "mattermost-adapter er under sit tilgængeligheds-SLO",
            "description": "SLO 99.9 % (docs/slo/mattermost-adapter.md)."
          }
        },
        {
          "alert": "ModuleLatencyAboveSLO",
          "expr": "module:latency:p95_seconds{module=\"mattermost-adapter\"} > 0.3",
          "for": "10m",
          "labels": {
            "severity": "warning",
            "module": "mattermost-adapter"
          },
          "annotations": {
            "summary": "mattermost-adapter har p95 over sit SLO",
            "description": "SLO 300 ms (docs/slo/mattermost-adapter.md)."
          }
        }
      ]
    },
    {
      "name": "platform-agents",
      "interval": "30s",
      "rules": [
        {
          "record": "platform:agent_actions:rate5m",
          "expr": "sum by (agent, verb, decision, autonomy_class) (rate(platform_agent_actions_total[5m]))"
        },
        {
          "alert": "AgentEscalationSpike",
          "expr": "sum(rate(platform_agent_escalations_total[5m])) > 0.1",
          "for": "5m",
          "labels": {
            "severity": "warning"
          },
          "annotations": {
            "summary": "Agent-eskaleringer over det normale",
            "description": "Loop-detektion eller budget pres; se agent-dashboardet."
          }
        },
        {
          "alert": "AgentBudgetExceeded",
          "expr": "increase(platform_agent_budget_exceeded_total[1h]) > 0",
          "for": "0m",
          "labels": {
            "severity": "critical"
          },
          "annotations": {
            "summary": "En agent har overskredet sit budget",
            "description": "Agenten skal have eskaleret til et menneske; verificér at den stoppede."
          }
        },
        {
          "alert": "AgentGatewayBypassDetected",
          "expr": "increase(platform_agent_gateway_bypass_total[1h]) > 0",
          "for": "0m",
          "labels": {
            "severity": "critical"
          },
          "annotations": {
            "summary": "Modelkald uden om AI-gatewayen",
            "description": "Direkte leverandørkald er forbudt (ADR-0006). Undersøg straks."
          }
        }
      ]
    }
  ]
}
